export const NATURAL_EARTH_VIEWBOX = '0 0 800 390';

export function projectNaturalEarth(lngDeg, latDeg) {
  const phi = (latDeg * Math.PI) / 180;
  const lambda = (lngDeg * Math.PI) / 180;
  const phi2 = phi * phi, phi4 = phi2 * phi2, phi6 = phi4 * phi2;
  const A0 = 0.870700, A1 = -0.131979, A2 = -0.003978, A3 = 0.001529, A4 = -0.001395, A5 = 0.000490, A6 = -0.000075;
  const X = lambda * (A0 + A1 * phi2 + A2 * phi4 + A3 * phi6 + A4 * phi6 * phi2 + A5 * phi6 * phi4 + A6 * phi6 * phi6);
  const B0 = 1.007226, B1 = 0.015085, B2 = -0.044475, B3 = 0.028874, B4 = -0.005916, B5 = 0.000843, B6 = -0.000057;
  const phi3 = phi * phi2, phi5 = phi3 * phi2, phi7 = phi5 * phi2, phi9 = phi7 * phi2, phi11 = phi9 * phi2, phi13 = phi11 * phi2;
  const Y = B0 * phi + B1 * phi3 + B2 * phi5 + B3 * phi7 + B4 * phi9 + B5 * phi11 + B6 * phi13;
  return {
    x: Number((400 + X * 136.9).toFixed(1)),
    y: Number((230 - Y * 136.9).toFixed(1))
  };
}
